import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));

  const handleSubmit = () => {
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        maxWidth: 480,
        padding: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      <JxDivider />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField
            label="Город"
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>Контакты</div>
          <div style={{ color: 'var(--jx-text)' }}>{fullName || '—'}</div>
          <div style={{ color: 'var(--jx-text)' }}>{email || '—'}</div>
          <div style={{ color: 'var(--jx-text)' }}>{phone || '—'}</div>

          <JxDivider />

          <div style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>Адрес</div>
          <div style={{ color: 'var(--jx-text)' }}>{address || '—'}</div>
          <div style={{ color: 'var(--jx-text)' }}>
            {city || '—'}
            {postalCode ? `, ${postalCode}` : ''}
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" type="button" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="button" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

